    compose_a_stage_63(a, entries, squares);
    compose_a_stage_64(a, entries, squares);
    compose_a_stage_65(a, entries, squares);
    compose_a_stage_66(a, entries, squares);
    compose_a_stage_67(a, entries, squares);
    compose_a_stage_68(a, entries);
    compose_a_stage_69(a, entries, squares);
    compose_a_stage_70(a, entries, squares);
    compose_a_stage_71(a, entries, squares);
    compose_a_stage_72(a, entries);
    compose_a_stage_73(a, entries, squares);
    compose_a_stage_74(a, entries);
    compose_a_stage_75(a, entries);
    compose_a_stage_76(a, entries, squares);
    compose_a_stage_77(a, entries, squares);
