    compose_a_stage_95(a, entries, squares);
    compose_a_stage_96(a, entries, squares);
    compose_a_stage_97(a, entries, squares);
    compose_a_stage_98(a, entries);
    compose_a_stage_99(a, entries, squares);
    compose_a_stage_100(a, entries);
    compose_a_stage_101(a, entries);
    compose_a_stage_102(a, entries, squares);
    compose_a_stage_103(a, entries, squares);
    compose_a_stage_104(a, entries, squares);
    compose_a_stage_105(a, entries, squares);
